123456789101112131415161718192021public class WaitingOperation {

    public static void perform(String name, int duration) {
        System.out.printf(&quot;wait for %s for %d seconds\n&quot;, name, duration);

        // 获取当前执行的vt
        var VirtualThread = VirtualThreadScheduler.CURRENT_VIRTUAL_THREAD.get();
        var timer = new Timer();
        timer.schedule(new TimerTask() {
            @Override
            public void run() {
                // 让vt继续执行
                SCHEDULER.scheduler(VirtualThread);
                timer.cancel();
            }
        }, duration * 1_000L);

        Continuation.yield(SCOPE);
    }

