malloc 和 free 成对使用

1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556#include 
#include 
#include 

int main(void)
{
    // 存储在栈中, 内存地址从大到小
    int a = 10;
    int b = 20;
    printf("&a = %p\n", &a); // &a = 0x16b90eb68
    printf("&b = %p\n", &b); // &b = 0x16b90eb64

    // 存储在栈中, 内存地址从小到大
    int* p1 = malloc(sizeof(int));
    *p1 = 10;
    int* p2 = malloc(sizeof(int));
    *p2 = 20;
    printf("p1 = %p\n", p1); //  p1 = 00762F48
    printf("p2 = %p\n", p2); // p2 = 00762F58
    free(p1);
    free(p2);

    // malloc 所在文件:stdlib.h
    // 申请堆内存空间并返回,所申请的空间并未初始化。
    /*
     * malloc
     * 第一个参数: 需要申请多少个字节空间
     * 返回值类型: void *
     */
    int* p = malloc(sizeof(int));
    printf("p = %i\n", *p); // *p可能是垃圾数据
    /*
     * 第一个参数: 需要初始化的内存地址
     * 第二个初始: 需要初始化的值
     * 第三个参数: 需要初始化对少个字节
     */
    memset(p, 0, sizeof(int)); // 对申请的内存空间进行初始化
    printf("p = %i\n", *p); // 初始化为0
    printf("&p = %p\n", p);
    *p = 20;
    printf("p = %i\n", *p);

    // realloc 扩容/缩容
    // 返回的指针，可能与 ptr 的值相同，也有可能不同。
    // 若相同，则说明在原空间后面申请，否则，则可能后续空间不足，重新申请的新的连续空间，原数据拷贝到新空间， 原有空间自动释放
    p = realloc(p, sizeof(int) * 2);
    printf("&p = %p\n", p);
    printf("p = %i\n", *p);

    // free stdlib.h
    // 通过malloc申请的存储空间一定要释放, 所以malloc和free函数总是成对出现
    // 释放申请的堆内存
    free(p);

    return 0;
}

链表实现#include 
#include 

typedef struct node
{
    int data;
    struct node* next;
} Node;

#define NODE_SIZE sizeof(Node)

// 创建一个空链表，包含一个头结点
Node* createNodeList();
// 尾插法
void insertTail(Node* head, int data);
// 头插法
void insertHead(Node* head, int data);
// 打印链表
void printNodeList(Node* node);
// 释放一个链表
void freeNode(Node* head);
// 计算链表长度
int listLength(const Node* head);
// 链表查找
Node* searchList(Node* head, int key);
// 链表删除
void deleteNodeList(Node* head, Node* find);
// 反转链表
void reverseList(Node* head);

int main(void)
{
    Node* head = createNodeList();
    if (!head)
    {
        exit(1);
    }
    insertHead(head, 1);
    insertHead(head, 2);
    insertTail(head, 3);
    insertTail(head, 4);
    printNodeList(head);
    reverseList(head);
    printNodeList(head);
    int length = listLength(head);
    printf("链表长度: %i\n", length);

    if (searchList(head, 4))
    {
        printf("找到了值为%i的节点\n", 4);
    }

    if (searchList(head, 2))
    {
        printf("找到了值为%i的节点\n", 2);
    }

    if (!searchList(head, 100))
    {
        printf("没找到值为%i的节点\n", 100);
    }

    deleteNodeList(head, searchList(head, 4));
    deleteNodeList(head, searchList(head, 2));

    printNodeList(head);

    free(head);
    return 0;
}

Node* createNodeList()
{
    Node* head = malloc(NODE_SIZE);
    if (head == NULL)
    {
        return NULL;
    }
    head->next = NULL;
    return head;
}

void insertTail(Node* head, int data)
{
    // 找到尾结点
    Node* pre = head;
    while (pre != NULL && pre->next != NULL)
    {
        pre = pre->next;
    }
    if (pre == NULL)
    {
        return;
    }
    Node* node = malloc(NODE_SIZE);
    node->data = data;
    node->next = NULL;
    pre->next = node;
}

void insertHead(Node* head, int data)
{
    Node* node = malloc(NODE_SIZE);
    node->data = data;
    node->next = head->next;
    head->next = node;
}

void printNodeList(Node* node)
{
    Node* head = node->next;
    while (head != NULL)
    {
        int currentData = head->data;
        printf("currentData = %i\n", currentData);
        head = head->next;
    }
}

void freeNode(Node* head)
{
    if (head == NULL)
    {
        return;
    }
    Node* cur = NULL;
    while (head != NULL)
    {
        cur = head->next;
        free(head);
        head = cur;
    }
}

// const Node* head 表示指针指向的内容不能修改
// Node* const head 表示这个指针不能修改
int listLength(const Node* head)
{
    if (head == NULL)
    {
        return 0;
    }
    int count = 0;
    head = head->next;
    while (head)
    {
        count++;
        head = head->next;
    }
    return count;
}

Node* searchList(Node* head, int key)
{
    if (!head)
    {
        return NULL;
    }
    head = head->next;
    while (head)
    {
        if (key == head->data)
        {
            break;
        }
        head = head->next;
    }
    return head;
}

void deleteNodeList(Node* head, Node* find)
{
    if (!head)
    {
        return;
    }
    while (head->next != find)
    {
        head = head->next;
    }
    if (head)
    {
        head->next = find->next;
        free(find);
    }
}

void reverseList(Node* head)
{
    Node *pre, *cur;
    pre = head->next;
    // 把head置为一个空链表
    head->next = NULL;
    while (pre)
    {
        // 反转链表，相当于头插法
        cur = pre->next;
        pre->next = head->next;
        head->next = pre;
        pre = cur;
    }
}

