兜底方案








上面的解决方案是没问题的，但是但是但是，某些开发者可能没有这个意识或者忘记了，导致异常还是被吞噬了
既然未捕获的异常最终会输出到 System.err 那么重新设置系统的 err 处理，把信息输出到日志系统中。下面这个是兜底方案，会存在部分的不合理，但是为了不丢异常信息还是可以容忍的，日常开发中发现此类异常，需要定位到对应的业务代码，用上面提供的解决方案完善代码；毕竟这只是一个兜底的方案，而不是常规方案
123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960@Component
public class Stderr {

    private static final Logger logErr = LoggerFactory.getLogger(&quot;[UnCatchError]&quot;);

    private static final PrintStream STDERR = new PrintStream(System.err) {

        @Override
        public void println(String x) {
            logErr.error(x);
        }

        @Override
        public void println(Object x) {
            logErr.error(&quot;&quot; + x);
        }

        @Override
        public void print(boolean b) {
            logErr.error(&quot;&quot; + b);
        }

        @Override
        public void print(char c) {
            logErr.error(&quot;&quot; + c);
        }

        @Override
        public void print(int i) {
            logErr.error(&quot;&quot; + i);
        }

        @Override
        public void print(long l) {
            logErr.error(&quot;&quot; + l);
        }

        @Override
        public void print(float f) {
            logErr.error(&quot;&quot; + f);
        }

        @Override
        public void print(double d) {
            logErr.error(&quot;&quot; + d);
        }

        @Override
        public void print(String s) {
            logErr.error(s);
        }

    };

    static {
        System.setErr(STDERR);
    }


}
